import Foundation
import KitFigures
import Testing

/// The port parses each shared fixture exactly as the terminal client's
/// reference does (ADR 0054). The fixtures are generated by the reference:
/// `KIT_UPDATE_FIGURE_FIXTURES=1 ard test test/figure_fixtures_test.ard` in
/// `apps/cli`. Each records the parsed figure, then the terminal's drawing or
/// layout, which this client doesn't make; or the reason the figure isn't drawn.
struct FigureFixtureTests {
    /// `testdata/figures` at the repository root, five levels above this file.
    static let directory = (0..<5).reduce(URL(fileURLWithPath: #filePath)) { url, _ in
        url.deletingLastPathComponent()
    }.appendingPathComponent("testdata/figures")

    static var names: [String] {
        let files = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
        return files.filter { $0.hasSuffix(".md") }.map { String($0.dropLast(3)) }.sorted()
    }

    @Test func fixturesArePresent() {
        #expect(Self.names.count >= 50)
    }

    @Test(arguments: names) func parsesLikeTheReference(_ name: String) throws {
        let source = try String(contentsOf: Self.directory.appendingPathComponent("\(name).md"), encoding: .utf8)
        let recorded = try String(contentsOf: Self.directory.appendingPathComponent("\(name).txt"), encoding: .utf8)
        // The parsed figure is everything before the drawing or layout.
        let cut = recorded.range(of: "\ndrawn ") ?? recorded.range(of: "\nlaid out ")
        let expected = cut.map { String(recorded[...$0.lowerBound]) } ?? recorded
        let lines = source.trimmingCharacters(in: .newlines).components(separatedBy: "\n")
        let info = String(lines[0].drop { $0 == "`" || $0 == "~" })
        let body = lines.dropFirst().dropLast().joined(separator: "\n")
        let actual: String
        switch Figure.parse(info: info, body: body) {
        case .success(let figure): actual = figure.record
        case .failure(let notDrawn): actual = "not drawn: \(notDrawn.reason)\n"
        }
        #expect(actual == expected, "\(name)")
    }
}
